import math

def sigmoid(z):
    if z >= 0:
        return 1 / (1 + math.exp(-z))
    e = math.exp(z)
    return e / (1 + e)

hours = [0.5, 1.0, 1.5, 2.0, 2.5, 3.0, 3.5, 4.0, 4.5, 5.0]
passed = [0, 0, 0, 1, 0, 1, 0, 1, 1, 1]
w, b, lr = 0.0, 0.0, 0.1

for step in range(3001):
    p = [sigmoid(w * x + b) for x in hours]
    if step in (0, 10, 100, 1000, 3000):
        loss = -sum(math.log(q) if y else math.log(1 - q) for q, y in zip(p, passed)) / len(p)
        print(step, round(loss, 4))
    dw = sum((q - y) * x for q, y, x in zip(p, passed, hours)) / len(p)
    db = sum(q - y for q, y in zip(p, passed)) / len(p)
    w, b = w - lr * dw, b - lr * db

print('w', round(w, 2), 'b', round(b, 2), '50% at', round(-b / w, 2), 'hours')
for x in (1.0, 2.75, 4.5):
    print(x, 'hours:', round(sigmoid(w * x + b), 2))

