    if z >= 0:
        return 1 / (1 + _m.exp(-z))
    e = _m.exp(z)
    return e / (1 + e)

def _ref(X, y, lr, steps):
    w, b = [0.0] * len(X[0]), 0.0
    for _ in range(steps):
        err = [_sig(sum(a * c for a, c in zip(w, r)) + b) - t for r, t in zip(X, y)]
        w, b = [wj - lr * sum(e * r[j] for e, r in zip(err, X)) / len(X) for j, wj in enumerate(w)], b - lr * sum(err) / len(X)
    return w, b

def _close(got, want, msg):
    gw, gb = got
    ww, wb = want
