import math


def sigmoid(z):
    if z >= 0:
        return 1 / (1 + math.exp(-z))
    e = math.exp(z)
    return e / (1 + e)


def fit_logistic(X, y, lr=0.1, steps=1000):
    if not X or len(X) != len(y) or any(len(row) != len(X[0]) for row in X):
        raise ValueError('need rows of equal length, one label each')
    if any(label not in (0, 1) for label in y) or lr <= 0 or steps < 0:
        raise ValueError('labels must be 0 or 1, lr positive and steps not negative')
    n, d = len(X), len(X[0])
    w, b = [0.0] * d, 0.0
    for _ in range(steps):
        err = [sigmoid(sum(wj * xj for wj, xj in zip(w, row)) + b) - label for row, label in zip(X, y)]
        dw = [sum(e * row[j] for e, row in zip(err, X)) / n for j in range(d)]
        db = sum(err) / n
        w = [wj - lr * g for wj, g in zip(w, dw)]
        b = b - lr * db
    return w, float(b)
